for (const item of $input.all()) {
  if (item.binary && item.binary.data) {
    const mt = item.binary.data.mimeType || '';
    if (!mt.startsWith('image/')) item.binary.data.mimeType = 'image/jpeg';
    item.binary.data.fileName = item.binary.data.fileName || 'cedula.jpg';
  }
}
return $input.all();

