const inp = $input.first();
const j = inp.json;
const msg = j.message || null;
const tieneBinario = !!(inp.binary && inp.binary.data);
return [{
  json: {
    chat_id: String(j.chat_id ?? (msg && msg.chat && msg.chat.id)),
    mensaje: j.mensaje ?? (msg && msg.text) ?? '',
    canal:   j.canal ?? 'telegram',
    message: msg,
    es_foto_tg: !!(msg && msg.photo),
    es_imagen_web: (j.canal === 'web' && tieneBinario)
  },
  binary: inp.binary
}];
